    h, w = len(grid), len(grid[0])
    out_h, out_w = 2 * h, 2 * w

    # Get corner values from input
    tl = grid[0][0]  # top-left value
    br = grid[-1][-1]  # bottom-right value

    result = [[0] * out_w for _ in range(out_h)]

    for r in range(out_h):
        for c in range(out_w):
            # Row 0 is all bottom-right value
            if r == 0:
                result[r][c] = br
            # Column 0 is all bottom-right value (except top-left is handled above)
            elif c == 0:
                result[r][c] = br
            else:
                # For remaining cells, use parity of coordinates
                if r % 2 == c % 2:  # both even or both odd
                    result[r][c] = tl
                else:
